#include <bits/stdc++.h>
using namespace std;

long long INF_VAL = 1e18;
long long total_answer = 0;
vector<int> cache_dp;

int get_min_moves(long long n) {
    if (n == 0) return 0;
    if (n < (long long)cache_dp.size() && cache_dp[n]) return cache_dp[n];

    long long prev_diff = INF_VAL;
    long long x = 1;
    int steps_count = 0;

    while (abs(x - n) <= prev_diff) {
        prev_diff = abs(x - n);
        x = x * 10 + 1;
        steps_count++;
    }
    x /= 10;

    if (x > n && x / 10) {
        if (n < (long long)cache_dp.size()) {
            return cache_dp[n] = min(steps_count + get_min_moves(abs(x - n)),
                                      steps_count - 1 + get_min_moves(abs(x/10 - n)));
        }
        return min(steps_count + get_min_moves(abs(x - n)),
                   steps_count - 1 + get_min_moves(abs(x/10 - n)));
    }
    if (n < (long long)cache_dp.size()) {
        return cache_dp[n] = steps_count + get_min_moves(abs(x - n));
    }
    return steps_count + get_min_moves(abs(x - n));
}

int main() {
    ios_base::sync_with_stdio(false);
    long long n; cin >> n;
    cache_dp.resize(1e7);
    cout << get_min_moves(n);
    return 0;
}
